import{_ as o,l,o as e,c as s,v as p,p as E,x as t,d as r,i as d,S as h,b as n}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"FinGPT","description":"","frontmatter":{"title":"FinGPT","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fingpt.md","filePath":"quant/fingpt.md","lastUpdated":1789023840000}'),u={name:"quant/fingpt.md"};function B(c,a,A,L,P,g){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=p('<h1 id="fingpt" tabindex="-1">FinGPT <a class="header-anchor" href="#fingpt" aria-label="Permalink to &quot;FinGPT&quot;">​</a></h1><div class="epigraph"><p>彭博一类专有模型吃的是独占数据；开源金融大模型的瓶颈首先是数据策展与低成本适配，而不是再从零训一个 50B。</p><footer>—— Yang, Liu and Wang, FinGPT: Open-Source Financial Large Language Models, arXiv:2306.06031，FinLLM @ IJCAI 2023</footer></div><p>Yang、Liu 与 Wang 把 FinGPT 写成面向金融的开源框架，而不是单一封闭权重。对照物是 Wu 等人的 BloombergGPT：50B、FinPile 混训、权重与语料不公开。FinGPT 的主张是数据中心：自动采集与清洗互联网上的金融文本，再用 LoRA / QLoRA 把通用基座适配到金融任务，成本比从零预训练低几个数量级。配套仓库 <code>AI4Finance-Foundation/FinGPT</code> 与 <code>FinNLP</code>。后续的数据中心长文（arXiv:2307.10485）补充实时数据管道与用市场价格当反馈的 RLSP；Instruct-FinGPT（arXiv:2306.12659）把指令微调对准情绪分类。本篇写框架的四层与它在量化研究里能合法承担的角色——特征提取、文档问答、情绪分数——以及它不能承担的角色：时间机器、自动下单、替代<a href="/quant/point-in-time">点-in-time</a> 基本面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>金融 NLP 的数据问题与通用语料不同：时效强、信噪比低、格式杂（网页、API、PDF、表、图）、版权与再分发受限，历史「当时可见」与数据库「现在看见」不一致。专有终端用内部新闻、研报与票据堆出领域优势；开源若只下载几份 10-K，适配出来的模型会在情绪与新闻分类上显得能打，一到实时与多源对账就塌。FinGPT 把问题从「有没有一个金融 GPT」改写成「有没有可复现的数据策展 + 轻量适配」。</p><p>第二个问题是目标错位。框架论文列举智能投顾、算法交易、低代码开发，作为应用层示例。量化研究若把示例当成已验证的 alpha，会把聊天能力与可交易预测混为一谈。Lopez-Lira 与 Tang（2023）表明新闻上的 LLM 情绪可以形成简单多空；那是受控实验，不是 FinGPT 仓库的默认策略。正确的问题是：在冻结的模型版本与冻结的时间戳下，文本特征相对 Loughran–McDonald 词典有多少增量，见<a href="/quant/news-nlp-alpha">舆情与文本</a>。</p><h3 id="从零预训练并不是开源的对称物" tabindex="-1">从零预训练并不是开源的对称物 <a class="header-anchor" href="#从零预训练并不是开源的对称物" aria-label="Permalink to &quot;从零预训练并不是开源的对称物&quot;">​</a></h3><p>BloombergGPT 的贡献是混训配方与评测协议，见<a href="/quant/bloomberggpt">BloombergGPT</a>。开源对称物不是「大家凑 700B token 再训 50B」，而是承认通用基座已经吸收了大量公开文本，金融增量主要在：专有时效数据、表格与数字、指令格式、以及偏好。LoRA 把增量放进低秩旁路，基座可换、适配可版本化。这与量化里「风险模型冻结、alpha 叠加」是同一类工程直觉。RLHF / RLSP 则把「什么叫好的金融回答」参数化；若奖励误用未来收益，适配本身就成为前视。</p><p><span class="marginnote">用事后发布的 GPT 给 2018 年的新闻打标签，知识截止日期与训练语料污染会造成系统性前视。文本因子的模型 ID、量化位数与提示词必须随 vintage 保存，与财务报表的 as-of 同一纪律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>四层。</strong> 数据源层：新闻、社交、公告、研报等尽可能广的覆盖，强调时效。数据工程层：去重、清洗、对齐时间戳，处理金融文本的低信噪与高时效。LLM 层：在通用基座上 LoRA / QLoRA，而不是改全部权重；可选 RLHF。应用层：情绪、投顾问答、低代码原型。数据中心论文把采集写成 \\(\\ge 34\\) 个公开源的自动化管道，并讨论 RLSP：用价格变动当弱监督，让模型对「事后涨了的新闻」更高权重——这在研究里极危险，必须把价格滞后到文本可获得之后，否则就是用 \\(r_{t+1}\\) 监督对 \\(\\mathcal{F}_t\\) 文本的拟合。</p><p><strong>适配配方。</strong> 指令数据应任务化：情绪、分类、摘要、抽取，而不是「请给出买入建议」。Instruct-FinGPT 用金融情绪指令微调，评测应落在分类 F1，而不是回测夏普。基座选择（ChatGLM、LLaMA、后续 Qwen 等）改变分词与中文能力，中英新闻不可混成同一 IDF。量化（QLoRA）省显存，但金融数字对分词敏感：价格、代码、百分号被切碎后，数字推理会 silently 错，评测必须单列。</p><p><strong>量化管道。</strong> 合法用法：把冻结模型当特征函数 \\(f(d_t)\\)，输出情绪、主题、事件类型，再截面 rank、行业市值中性，walk-forward。非法用法：让模型读到当日收盘后再解释当日新闻、或在回测环里调用会检索「当前网页」的工具。检索应指向带时间戳的本地语料快照，见<a href="/quant/finsearchcomp">FinSearchComp</a> 对时效与来源对账的要求。</p><h3 id="开源许可与版权不是评测指标" tabindex="-1">开源许可与版权不是评测指标 <a class="header-anchor" href="#开源许可与版权不是评测指标" aria-label="Permalink to &quot;开源许可与版权不是评测指标&quot;">​</a></h3><p>框架鼓励共享数据管道，不鼓励把受版权保护的研报全文重分发进训练仓。特征应是计数、嵌入与模型输出。个人社交媒体定向与未授权全文，既有法律风险，也不是 alpha 必需。中文分词、否定与反讽使英文金融词典不能硬译；中文适配需要中文指令与中文评测，见<a href="/quant/ctbench">CTBench 中文金融基准</a>。</p><p><span class="marginnote">LoRA 秩与训练步数是超参。在测试年的情绪准确率上挑秩，等于用测试做训练。适配只允许在验证段早停，与<a href="/quant/gbdt-alpha">GBDT</a> 的早停是同一规则。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数据中心起作用的机制是覆盖与新鲜度：同一事件在路透、本地媒体与监管公告上的到达时间不同，模型若只在英文通用语料里见过公司名，对中文公告的实体与数字会弱。轻量适配起作用的机制是：通用基座已有句法与世界知识，金融任务需要的是术语、格式与「何谓负面」的领域校准（Loughran–McDonald 对通用词典的批评在 LLM 里变成「通用情绪头」）。LoRA 不创造新的市场信息，它改变条件分布 \\(p(\\text{标签}\\mid\\text{文本})\\)。</p><p>RLSP 若用同期收益，学到的可能是风险溢价与关注度，而不是因果情绪。价格已经是公开信息的函数；文本的增量必须来自尚未进入价格的注意或尚未进入会计数字的信息。用 \\(r_{t}\\) 强化对 \\(t\\) 日新闻的解释，模型会把「大跌当日的新闻」记成负面模板，样本外遇到同样模板但价格已调整时失效。合法的弱监督是滞后收益或分析师修订，并且报告相对词典基线的增量，而不是绝对准确率。</p><p>与 BloombergGPT 的分工：混训从零改的是先验，适配改的是任务头。闭源模型在内部票据分类上可以很强，却无法进入可复现研究。FinGPT 的可复现性来自管道与适配器，不来自「开源所以更会交易」。</p><h3 id="幻觉、数字与代码" tabindex="-1">幻觉、数字与代码 <a class="header-anchor" href="#幻觉、数字与代码" aria-label="Permalink to &quot;幻觉、数字与代码&quot;">​</a></h3><p>生成式应用层会编造未出现的营收数字、把表格加错行。量化使用应把 LLM 限制在分类与抽取，数字计算交给确定性代码，再在<a href="/quant/edinet-bench">长文档基准</a>与<a href="/quant/finmmdocr">多模态文档</a>上测抽取误差。低代码「生成策略」若直接下单，把自然语言的不稳定性送进订单状态机；正确边界是生成假设，假设必须编译成可审计的算子树，对照<a href="/quant/kakushadze-101-alphas">101 公式</a> 或冻结的特征定义。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用在线 API 回放历史：供应商模型会升级，网页会变。不要把 FinGPT 演示笔记本里的交易示例当样本外。不要用未经授权的全文做继续预训练后对外发布权重。评测应同时报金融任务与通用任务，以免适配把模型变成只会选 ABCD 的考试机。中文公告的到达时钟以本地可获得为准。</p><p>版本治理：基座哈希、LoRA 文件、提示词、语料截止日期、分词器，五者绑定。换基座必须重跑验证，而不是假设适配器可热插拔。闸门上，模型输出不得直接改仓位；仓位来自特征与优化器，模型只是特征函数之一，见<a href="/quant/trading-kill-switch">交易闸门</a>。</p><p><span class="marginnote">「Democratizing FinLLMs」是数据与权重的政治学表述。交易上没有民主：容量与冲击仍按<a href="/quant/sqrt-impact">平方根</a>收费。开源降低的是研究准入，不是市场冲击。</span></p>',26)),(e(),E(h,null,{default:t(()=>[d(i,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%B8%A6%E6%97%B6%E6%88%B3%E7%9A%84%E5%85%AC%E5%BC%80%E9%87%91%E8%9E%8D%E6%BA%90%22%5D%20--%3E%20ENG%5B%22%E6%B8%85%E6%B4%97%20%2F%20%E5%8E%BB%E9%87%8D%20%2F%20PIT%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20ENG%20--%3E%20LORA%5B%22%E5%9F%BA%E5%BA%A7%20%2B%20LoRA%20%E9%80%82%E9%85%8D%22%5D%0A%20%20LORA%20--%3E%20FEAT%5B%22%E6%83%85%E7%BB%AA%20%2F%20%E4%BA%8B%E4%BB%B6%20%2F%20%E6%8A%BD%E5%8F%96%E7%89%B9%E5%BE%81%22%5D%0A%20%20FEAT%20--%3E%20CS%5B%22%E6%88%AA%E9%9D%A2%E4%B8%AD%E6%80%A7%E4%B8%8E%E6%BB%9E%E5%90%8E%22%5D%0A%20%20CS%20--%3E%20OOS%5B%22%E7%9B%B8%E5%AF%B9%E8%AF%8D%E5%85%B8%E7%9A%84%E5%A2%9E%E9%87%8F%20IC%22%5D%0A%20%20LORA%20--%3E%20APP%5B%22%E9%97%AE%E7%AD%94%E4%B8%8E%E6%91%98%E8%A6%81%EF%BC%9A%E4%B8%8D%E7%9B%B4%E6%8E%A5%E4%B8%8B%E5%8D%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n("h2",{id:"小结",tabindex:"-1"},[r("小结 "),n("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=n("ul",null,[n("li",null,"FinGPT（Yang, Liu, Wang, arXiv:2306.06031）是数据中心的开源 FinLLM 框架：策展管道 + LoRA，对照 Wu 等人闭源的 BloombergGPT。"),n("li",null,"合法量化用途是冻结版本下的文本特征；非法用途是用未来模型或未来网页给历史打标签、或把生成建议直接当订单。"),n("li",null,"Instruct-FinGPT 与数据中心续作补充指令微调与弱监督；RLSP 必须把价格严格滞后。"),n("li",null,"数字计算与策略逻辑应落在确定性代码，LLM 负责分类、抽取与假设草稿。"),n("li",null,"出处：Yang, Liu and Wang, arXiv:2306.06031；数据中心框架 arXiv:2307.10485；Instruct-FinGPT arXiv:2306.12659；对照 Wu et al., BloombergGPT, arXiv:2303.17564。")],-1))])}const f=o(u,[["render",B]]);export{F as __pageData,f as default};
